-- =============================================================================
-- Uzbek Error DNA — starter content.
--
-- error_catalog: an original, hand-written starter set (30 entries) meant to
-- prove out the whole pipeline end-to-end. It is NOT the "100-error catalog,
-- built from real teacher/student interviews" the strategy doc calls for —
-- that still needs to happen with real linguistic research.
--
-- diagnostic_questions: 40 questions (8 per category), authored content
-- supplied by the founder. Each attempt samples 4 of the 8 per category —
-- see submit_diagnostic() / the client-side stratified sampler.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- error_catalog — 6 entries per category, 30 total
-- ---------------------------------------------------------------------------
insert into error_catalog (category, wrong_example, correct_example, uzbek_root_cause, explanation, order_index) values
  ('articles', 'I saw beautiful girl.', 'I saw a beautiful girl.', 'O''zbek tilida artikl tushunchasi umuman yo''q — ot oldiga hech narsa qo''shilmaydi.', 'Ingliz tilida sanaladigan ot birlikda ishlatilganda deyarli har doim a/an yoki the kerak.', 1),
  ('articles', 'She is best student in class.', 'She is the best student in the class.', 'Superlativ va yagona narsalar bilan "the" ishlatilishi zarurligi unutiladi.', 'Eng ustun daraja (best, tallest, first) deyarli har doim "the" bilan keladi.', 2),
  ('articles', 'I want to be doctor.', 'I want to be a doctor.', 'Kasb nomlaridan oldin artikl kerakligi tushunilmaydi.', '"be/become + kasb" tuzilishida kasb nomidan oldin "a/an" majburiy.', 3),
  ('articles', 'Sun rises in east.', 'The sun rises in the east.', 'Yagona/noyob obyektlar (sun, moon, sky) va tomon nomlari bilan "the" zarurligi bilinmaydi.', 'Dunyoda bittadan bo''ladigan narsalar (sun, moon) doim "the" bilan ishlatiladi.', 4),
  ('articles', 'He plays guitar every day.', 'He plays the guitar every day.', 'Musiqa asboblari bilan "the" ishlatilishi qoidasi ona tilida yo''q.', '"Play + musiqa asbobi" tuzilishida asbob nomidan oldin "the" kerak.', 5),
  ('articles', 'I go to school by a bus.', 'I go to school by bus.', 'Aksincha xato — transport turi bilan artikl QO''YILMASLIGI kerak bo''lgan joyda giperkorreksiya sodir bo''ladi.', '"By + transport turi" ("by bus", "by car") iborasida artikl ishlatilmaydi.', 6),

  ('prepositions', 'I am interesting about music.', 'I am interested in music.', '"-ing"/"-ed" farqi va preposition tanlovi ikkalasi ham bir vaqtda chalkashadi.', '"Interested in" — biror narsaga qiziqish; "interesting" — narsaning o''zi qiziqarli ekanini bildiradi.', 7),
  ('prepositions', 'I arrived to Tashkent yesterday.', 'I arrived in Tashkent yesterday.', '"Bormoq" ma''nosidagi fe''llar bilan "to" ishlatish odati barcha joy fe''llariga ko''chiriladi.', '"Arrive in/at" qoliplashgan birikma, "to" bilan ishlatilmaydi.', 8),
  ('prepositions', 'She is married with a doctor.', 'She is married to a doctor.', 'O''zbekcha "bilan" so''zi to''g''ridan-to''g''ri "with" deb tarjima qilinadi.', '"Married to" — inglizchada qoliplashgan ibora, "with" emas.', 9),
  ('prepositions', 'I depend from my parents.', 'I depend on my parents.', 'Rus tili ta''siri ("зависеть от") orqali "from" tanlab olinadi.', '"Depend on" — inglizchada yagona to''g''ri birikma.', 10),
  ('prepositions', 'We discussed about the problem.', 'We discussed the problem.', '"About" "haqida gapirish" fe''llariga avtomatik qo''shib yuboriladi, lekin "discuss" allaqachon tranzitiv fe''l.', '"Discuss" o''ziga to''g''ridan-to''g''ri to''ldiruvchi oladi, "about" ortiqcha.', 11),
  ('prepositions', 'I''m good in mathematics.', 'I''m good at mathematics.', '"-da/-de" kelishigi to''g''ridan-to''g''ri "in" bilan tarjima qilinadi.', 'Mahorat/qobiliyat bildirishda "good at" ishlatiladi, "good in" emas.', 12),

  ('tense', 'Yesterday I go to school.', 'Yesterday I went to school.', 'O''zbek tilida vaqt qo''shimchasi so''z bilan ifodalanadi, ingliz tilida esa fe''lning o''zi o''zgarishi kerak — o''quvchi buni unutadi.', 'Aniq o''tgan vaqt so''zi (yesterday) bo''lsa, fe''l Past Simple shaklida bo''lishi kerak.', 13),
  ('tense', 'I am living here since 2015.', 'I have been living here since 2015.', 'O''zbek tilida "hozirgi tugallanmagan zamon" tushunchasi alohida ajratilmagan.', '"Since + sana" bilan Present Perfect Continuous ishlatiladi, oddiy Present Continuous emas.', 14),
  ('tense', 'I have seen him yesterday.', 'I saw him yesterday.', 'Present Perfect va Past Simple farqi tushunilmagani uchun aniq o''tgan payt bilan ham Present Perfect ishlatiladi.', '"Yesterday" kabi aniq o''tgan payt so''zlari bilan faqat Past Simple ishlatiladi.', 15),
  ('tense', 'If I will have money, I will travel.', 'If I have money, I will travel.', 'Shart ergash gapida ikkala qismda ham kelasi zamon ishlatish tabiiy tuyuladi.', 'Zero/First Conditional''da "if" qismida Present Simple, natija qismida "will" ishlatiladi.', 16),
  ('tense', 'I am knowing the answer.', 'I know the answer.', 'Holat fe''llari (know, want, like, need) davomiy zamonda ishlatilmasligi tushunilmaydi.', 'Stative fe''llar odatda -ing shaklida ishlatilmaydi.', 17),
  ('tense', 'She has go to Moscow last year.', 'She went to Moscow last year.', 'Present Perfect va Past Simple formalari aralashtiriladi — "has" + noto''g''ri fe''l shakli qo''shiladi.', 'Aniq o''tgan yil ko''rsatilganda Past Simple ("went") ishlatiladi, Present Perfect emas.', 18),

  ('word_order', 'Always I eat breakfast at 7.', 'I always eat breakfast at 7.', 'SOV tuzilishiga ko''ra ravishlar gap boshiga qo''yiladi, lekin ingliz tilida ular fe''ldan oldin joylashadi.', 'Chastota ravishlari (always, usually, never) asosiy fe''ldan oldin, "be" fe''lidan keyin keladi.', 19),
  ('word_order', 'I very like this song.', 'I like this song very much.', '"Juda" so''zi sifat/fe''ldan oldin to''g''ridan-to''g''ri tarjima qilib qo''yiladi.', '"Very" fe''llarni emas, sifatlarni kuchaytiradi; fe''l uchun "very much" jumla oxirida ishlatiladi.', 20),
  ('word_order', 'What you are doing?', 'What are you doing?', 'Savol gaplarida yordamchi fe''l va ega o''rinlarini almashtirish (inversiya) unutiladi.', 'Ingliz tilida savol gaplarida yordamchi fe''l egadan OLDIN keladi.', 21),
  ('word_order', 'My father car is red.', 'My father''s car is red.', 'Egalik o''zbek tilida so''z oxiriga qo''shimcha bilan ifodalanadi, ingliz tilidagi apostrof unutiladi.', 'Shaxs egaligini bildirish uchun " ''s " qo''shilishi kerak.', 22),
  ('word_order', 'Book red is on the table.', 'The red book is on the table.', 'Sifat otdan keyin kelishi mumkin bo''lgan tuzilishlar ta''sirida joylashuv aralashadi.', 'Ingliz tilida sifat har doim otdan OLDIN keladi.', 23),
  ('word_order', 'Yesterday night I didn''t sleep well.', 'Last night I didn''t sleep well.', 'Vaqt birikmalari so''zma-so''z tarjima qilinadi — "kecha kechasi" to''g''ridan-to''g''ri "yesterday night" deb yozib yuboriladi.', '"O''tgan kecha" ma''nosida inglizchada qoliplashgan ibora — "last night".', 24),

  ('vocabulary', 'I went to the magazin to buy bread.', 'I went to the shop to buy bread.', 'Rus tilidagi "магазин" so''zi ingliz "magazine" (jurnal) bilan aralashtiriladi.', '"Magazine" — jurnal; do''kon uchun "shop" yoki "store" ishlatiladi.', 25),
  ('vocabulary', 'He is very sympathetic, everyone likes him.', 'He is very likeable, everyone likes him.', '"Sympathetic" inglizchada "hamdard" ma''nosini beradi, "yoqimli" emas — bu false friend.', '"Yoqimli/kirishimli" uchun "likeable" yoki "friendly" ishlatiladi.', 26),
  ('vocabulary', 'I have a lot of informations.', 'I have a lot of information.', '"Information" sanalmaydigan ot ekanligi bilinmaydi, ko''plik qo''shimchasi qo''shib yuboriladi.', '"Information" har doim birlik shaklda, ko''plikda ishlatilmaydi.', 27),
  ('vocabulary', 'Actually, I work as a teacher every day.', 'Actually, I meant something different.', '"Actually" so''zi "hozirda" deb noto''g''ri tushuniladi, aslida "aslida/haqiqatan" ma''nosini beradi.', '"Actually" kutilganidan farqli haqiqatni bildiradi, "hozirda/hozirgi vaqtda" emas.', 28),
  ('vocabulary', 'I will control my homework before submitting.', 'I will check my homework before submitting.', '"Control" so''zi "tekshirmoq" ma''nosida ishlatiladi, lekin inglizchada "boshqarmoq/nazorat qilmoq" ma''nosini beradi.', '"Tekshirmoq" uchun "check" ishlatiladi, "control" emas.', 29),
  ('vocabulary', 'My friend is very nervous, she gets angry quickly.', 'My friend is quick-tempered, she gets angry quickly.', '"Nervous" so''zi "asabiy/tez achchiqlanadigan" ma''nosida ishlatiladi, lekin inglizchada "xavotirli" ma''nosini beradi.', '"Tez achchiqlanadigan" uchun "quick-tempered" yoki "short-tempered" ishlatiladi.', 30);

-- ---------------------------------------------------------------------------
-- diagnostic_questions — 8 per category, 40 total
-- ---------------------------------------------------------------------------
insert into diagnostic_questions (category, prompt, options, correct_index, explanation, order_index) values
  ('articles', 'Choose the correct sentence:',
    array['I saw beautiful sunset.', 'I saw a beautiful sunset.', 'I saw the beautiful sunset.', 'I saw beautiful the sunset.'],
    1, 'O''zbekchada article yo''q, shuning uchun biz ''a'' ni tushirib qoldiramiz. Ingliz tilida sanaladigan ot oldida ''a'' kerak: a beautiful sunset.', 1),
  ('articles', 'Choose the correct sentence:',
    array['She is best student in class.', 'She is a best student in class.', 'She is the best student in class.', 'She is best the student in class.'],
    2, 'Superlative (eng yaxshi) oldida doim ''the'' keladi: the best. O''zbekchada ''eng yaxshi'' oldiga hech narsa qo''ymaymiz, shuning uchun bu xato ko''p uchraydi.', 2),
  ('articles', 'Choose the correct sentence:',
    array['He is an university student.', 'He is a university student.', 'He is university student.', 'He is the university student.'],
    1, '''University'' harfi ''u'' bo''lsa ham, tovushi ''yu'' (undosh) bo''lib eshitiladi, shuning uchun ''a'' ishlatiladi, ''an'' emas. Tovushga qaraymiz, harfga emas.', 3),
  ('articles', 'Choose the correct sentence:',
    array['I want to be doctor.', 'I want to be a doctor.', 'I want to be the doctor.', 'I want to be doctors.'],
    1, 'Kasb aytilganda ''a'' kerak: a doctor, a teacher, an engineer. O''zbekchada ''shifokor bo''laman'' — article yo''q, shuning uchun tushirib qoldiramiz.', 4),
  ('articles', 'Choose the correct sentence:',
    array['Sun rises in the east.', 'A sun rises in the east.', 'The sun rises in the east.', 'Sun rises in east.'],
    2, 'Yagona, noyob narsalar oldida ''the'' keladi: the sun, the moon, the earth. Faqat bitta quyosh bor, shuning uchun ''the''.', 5),
  ('articles', 'Choose the correct sentence:',
    array['I have information for you.', 'I have an information for you.', 'I have a information for you.', 'I have the informations for you.'],
    0, '''Information'' sanalmaydigan ot, shuning uchun ''a/an'' olmaydi va ko''plikda ishlatilmaydi. Bu o''zbek o''quvchilar uchun juda qiyin qoida.', 6),
  ('articles', 'Choose the correct sentence:',
    array['She plays the piano very well.', 'She plays piano very well.', 'She plays a piano very well.', 'She plays pianos very well.'],
    0, 'Musiqa asboblari oldida ''the'' keladi: play the piano, the guitar. O''zbekcha tarjimada bu his qilinmaydi, shuning uchun tushirib qoldiriladi.', 7),
  ('articles', 'Choose the correct sentence:',
    array['I go to school by bus.', 'I go to the school by bus.', 'I go to a school by bus.', 'I go to school by the bus.'],
    0, '''Go to school'', ''go to work'', ''by bus'' — bu turg''un iboralarda article ishlatilmaydi. Yodlab olish kerak.', 8),

  ('prepositions', 'Choose the correct sentence:',
    array['I am interesting about history.', 'I am interested in history.', 'I am interested about history.', 'I am interesting in history.'],
    1, '''Interested IN'' — doim ''in'' bilan keladi. Va odam ''interested'' (qiziqadi), narsa ''interesting'' (qiziq). O''zbekchada ikkalasi bitta so''z — ''qiziqarli''.', 9),
  ('prepositions', 'Choose the correct sentence:',
    array['I will meet you in Monday.', 'I will meet you on Monday.', 'I will meet you at Monday.', 'I will meet you to Monday.'],
    1, 'Kunlar oldida ''on'' keladi: on Monday, on Friday. Oylar/yillar oldida ''in'', aniq vaqt oldida ''at''. Bu tizimni yodlash kerak.', 10),
  ('prepositions', 'Choose the correct sentence:',
    array['She is good in English.', 'She is good at English.', 'She is good on English.', 'She is good with English.'],
    1, '''Good AT something'' — biror narsani yaxshi bilish/uddalash. O''zbekcha ''ingliz tilida yaxshi'' tuzilishi ''in'' ishlatishga undaydi, lekin to''g''risi ''at''.', 11),
  ('prepositions', 'Choose the correct sentence:',
    array['I live in Tashkent at Chilonzor street.', 'I live in Tashkent on Chilonzor street.', 'I live at Tashkent in Chilonzor street.', 'I live on Tashkent at Chilonzor street.'],
    1, 'Shahar oldida ''in'' (in Tashkent), ko''cha oldida ''on'' (on Chilonzor street). Kattadan kichikka: in > on > at.', 12),
  ('prepositions', 'Choose the correct sentence:',
    array['I depend of my parents.', 'I depend on my parents.', 'I depend from my parents.', 'I depend to my parents.'],
    1, '''Depend ON'' — doim ''on''. Bu ko''p tillarda ''from/of'' bilan keladi, shuning uchun xato ko''p bo''ladi. Ingliz tilida faqat ''on''.', 13),
  ('prepositions', 'Choose the correct sentence:',
    array['We arrived to the airport late.', 'We arrived at the airport late.', 'We arrived in the airport late.', 'We arrived on the airport late.'],
    1, '''Arrive AT'' (aniq joy) yoki ''arrive IN'' (shahar/mamlakat). ''Arrive to'' — umuman noto''g''ri. O''zbekcha ''-ga keldik'' ''to'' ni undaydi.', 14),
  ('prepositions', 'Choose the correct sentence:',
    array['I am married with a teacher.', 'I am married to a teacher.', 'I am married on a teacher.', 'I am married at a teacher.'],
    1, '''Married TO someone'' — doim ''to''. Ko''p tillarda ''with'' ishlatiladi (kimdir bilan), lekin ingliz tilida ''to''.', 15),
  ('prepositions', 'Choose the correct sentence:',
    array['Listen me carefully.', 'Listen to me carefully.', 'Listen at me carefully.', 'Listen for me carefully.'],
    1, '''Listen TO someone'' — ''to'' kerak. O''zbekcha ''meni tingla'' to''g''ridan-to''g''ri, shuning uchun ''to'' tushirib qoldiriladi.', 16),

  ('tense', 'Choose the correct sentence:',
    array['Yesterday I go to the market.', 'Yesterday I went to the market.', 'Yesterday I gone to the market.', 'Yesterday I going to the market.'],
    1, '''Yesterday'' o''tgan zamon signal so''zi. Fe''l Past Simple bo''lishi kerak: go → went. O''zbekcha bir fe''l shakli bo''lgani uchun bu chalkashadi.', 17),
  ('tense', 'Choose the correct sentence:',
    array['I am living here since 2010.', 'I have lived here since 2010.', 'I live here since 2010.', 'I lived here since 2010.'],
    1, '''Since'' bilan Present Perfect keladi (have lived) — o''tmishda boshlanib hozirgacha davom etayotgan ish. O''zbekchada bu farq yo''q.', 18),
  ('tense', 'Choose the correct sentence:',
    array['She don''t like coffee.', 'She doesn''t like coffee.', 'She not like coffee.', 'She isn''t like coffee.'],
    1, '3-shaxs birlik (she/he/it) uchun ''doesn''t'' kerak, ''don''t'' emas. O''zbekchada fe''l shaxsga qarab o''zgarmaydi, shuning uchun bu doim xato bo''ladi.', 19),
  ('tense', 'Choose the correct sentence:',
    array['When I was child, I played football.', 'When I was a child, I used to play football.', 'When I was a child, I am playing football.', 'When I was child, I play football.'],
    1, 'O''tmishdagi takroriy odat uchun ''used to'' ishlatiladi. Va ''a child'' — article kerak. Ikkita qoida bir gapda.', 20),
  ('tense', 'Choose the correct sentence:',
    array['I will call you when I will arrive.', 'I will call you when I arrive.', 'I call you when I will arrive.', 'I will call you when I arrived.'],
    1, '''When'' dan keyin kelasi zamonda ''will'' ishlatilmaydi — Present Simple keladi (arrive). Bu o''zbek o''quvchilar uchun juda qiyin qoida.', 21),
  ('tense', 'Choose the correct sentence:',
    array['How long you are studying English?', 'How long have you been studying English?', 'How long you study English?', 'How long you studied English?'],
    1, 'Davom etayotgan muddat uchun Present Perfect Continuous (have been studying). Va savol tuzilishida yordamchi fe''l oldinga chiqadi.', 22),
  ('tense', 'Choose the correct sentence:',
    array['I didn''t went to school today.', 'I didn''t go to school today.', 'I don''t went to school today.', 'I not went to school today.'],
    1, '''Did'' allaqachon o''tgan zamonni ko''rsatadi, shuning uchun asosiy fe''l asosiy shaklda qoladi: didn''t GO, went emas. Ikki marta o''tgan zamon bo''lmaydi.', 23),
  ('tense', 'Choose the correct sentence:',
    array['If I will have time, I will help you.', 'If I have time, I will help you.', 'If I had time, I will help you.', 'If I have time, I help you.'],
    1, 'First Conditional: ''if'' qismida Present Simple (have), asosiy qismda ''will''. ''If'' dan keyin ''will'' ishlatilmaydi.', 24),

  ('word_order', 'Choose the correct sentence:',
    array['Always I drink tea in the morning.', 'I always drink tea in the morning.', 'I drink always tea in the morning.', 'I drink tea always in the morning.'],
    1, 'Chastota ravishlari (always, usually, often) asosiy fe''ldan OLDIN keladi: I always drink. O''zbekchada ''doim'' gap boshiga qo''yiladi, shuning uchun bu xato ko''p.', 25),
  ('word_order', 'Choose the correct sentence:',
    array['I have a car red.', 'I have a red car.', 'I a red car have.', 'I red car have.'],
    1, 'Ingliz tilida sifat otdan OLDIN keladi: red car. O''zbekchada ham sifat oldin keladi, lekin ba''zilar ''car red'' deb tarjima qiladi.', 26),
  ('word_order', 'Choose the correct sentence:',
    array['Where you are going?', 'Where are you going?', 'Where you going?', 'Where going you are?'],
    1, 'Savolda yordamchi fe''l (are) subyektdan OLDIN keladi: Where ARE you going. O''zbekchada so''z tartibi o''zgarmaydi, shuning uchun bu qiyin.', 27),
  ('word_order', 'Choose the correct sentence:',
    array['I know not the answer.', 'I don''t know the answer.', 'I not know the answer.', 'I know don''t the answer.'],
    1, 'Inkor uchun ''don''t/doesn''t'' + asosiy fe''l kerak: I don''t know. O''zbekcha ''-ma'' qo''shimchasi fe''l ichida, ingliz tilida alohida so''z.', 28),
  ('word_order', 'Choose the correct sentence:',
    array['She speaks very well English.', 'She speaks English very well.', 'She very well speaks English.', 'She English speaks very well.'],
    1, 'Tarz ravishi (very well) obyektdan KEYIN keladi: speaks English very well. O''zbekchada ''juda yaxshi'' fe''ldan oldin turadi.', 29),
  ('word_order', 'Choose the correct sentence:',
    array['Do you know where is the station?', 'Do you know where the station is?', 'Do you know where station is?', 'Do you know is where the station?'],
    1, 'Bilvosita savolda (indirect question) so''z tartibi oddiy gapdek: where the station IS. To''g''ridan-to''g''ri savoldagidek ''is the station'' emas.', 30),
  ('word_order', 'Choose the correct sentence:',
    array['I like very much this song.', 'I like this song very much.', 'I very much like this song.', 'I this song like very much.'],
    1, '''Very much'' gap oxiriga keladi: I like this song very much. O''zbekcha ''bu qo''shiqni juda yaxshi ko''raman'' tuzilishi chalkashtiradi.', 31),
  ('word_order', 'Choose the correct sentence:',
    array['He gave to me a book.', 'He gave me a book.', 'He gave a book to me.', 'He me gave a book.'],
    1, '''Give someone something'' — ''to'' kerak emas: gave me a book. ''To me'' bo''lsa tartib boshqacha: gave a book to me. Ikkalasi to''g''ri, lekin ''gave to me a book'' xato.', 32),

  ('vocabulary', 'Choose the correct word. I bought a new phone from the ___.',
    array['magazine', 'shop', 'market''s magazine', 'librarian'],
    1, '''Magazin'' o''zbekchada do''kon, lekin inglizcha ''magazine'' — jurnal! Do''kon = shop/store. Bu klassik ''yolg''on do''st'' (false friend).', 33),
  ('vocabulary', 'Choose the correct word. My father works as a ___ in a company.',
    array['director', 'manager', 'chef', 'artist'],
    1, 'Kompaniyada ''manager'' (menejer). ''Chef'' — oshpaz, ''director'' aslida boshqaruvchi lekin kontekstga bog''liq. ''Artist'' — rassom.', 34),
  ('vocabulary', 'Choose the correct word. I need to ___ my English before the exam.',
    array['repeat', 'improve', 'translate', 'correct'],
    1, '''Improve'' — yaxshilash. O''zbek o''quvchilar ko''pincha ''repeat'' (takrorlash) ishlatadi, lekin bu yerda ''improve'' to''g''ri.', 35),
  ('vocabulary', 'Choose the correct word. She is very ___ and always helps others.',
    array['sympathetic', 'kind', 'comfortable', 'actual'],
    1, '''Kind'' — mehribon. ''Sympathetic'' hamdard degani, ''simpatichniy'' emas. ''Comfortable'' — qulay, odam haqida ishlatilmaydi. Yana false friendlar.', 36),
  ('vocabulary', 'Choose the correct word. The weather is very ___ today.',
    array['hot', 'warm', 'boiling', 'temperature'],
    1, '''Warm'' — iliq (yoqimli). ''Hot'' — juda issiq. Kontekstga qarab tanlanadi. ''Temperature'' — harorat, sifat emas.', 37),
  ('vocabulary', 'Choose the correct word. Can you ___ me how to solve this?',
    array['learn', 'teach', 'study', 'know'],
    1, '''Teach'' — o''rgatish (boshqaga). ''Learn'' — o''rganish (o''zing). O''zbekcha ''o''rgatmoq/o''rganmoq'' chalkashadi. Bu yerda ''teach me'' to''g''ri.', 38),
  ('vocabulary', 'Choose the correct word. I ___ a lot of money on books last month.',
    array['spent', 'spend', 'paid', 'bought'],
    0, '''Spend money ON something'' — pul sarflash. O''tgan zamon ''spent''. ''Pay'' to''lash (aniq narsaga), ''buy'' sotib olish. Kontekst ''spent'' ni talab qiladi.', 39),
  ('vocabulary', 'Choose the correct word. This exam was very ___, I couldn''t answer half.',
    array['difficult', 'hard', 'heavy', 'strong'],
    0, '''Difficult'' yoki ''hard'' — qiyin. ''Heavy'' — og''ir (vazn), imtihon uchun ishlatilmaydi. Ikkalasi to''g''ri bo''lsa ham ''difficult'' rasmiyroq va IELTS uchun yaxshiroq.', 40);
